--
Slice 1 of [Release 2: implementation](https://github.com/chrisdoc/surveybeat-next/issues/101).

## Goal
An Organization admin can turn AI processing on, and the Organization Durable Object has a client that can call the model exactly as ADR 0015 allows, and no other way.

## Acceptance criteria
- Organization setting `aiProcessing` (off by default) in the Organization Durable Object, with an Organization admin toggle on the Settings screen that explains what is sent, to whom (OpenRouter, Google Cloud or AWS in the EU), and that nothing is kept.
- While it is on, the answer page and the Invitation and Reminder emails state that redacted comments are processed by an AI service in the EU that keeps nothing (catalog copy).
- An `AiClient` service (domain interface, Cloudflare adapter) that POSTs to OpenRouter Chat Completions with the exact request shape of ADR 0015: `anthropic/claude-haiku-5.5`, `provider.zdr: true`, `only`/`order` = `google-vertex/europe`, `amazon-bedrock/eu-west-1`, `allow_fallbacks: false`, `data_collection: deny`, strict `json_schema`, capped `max_tokens`, low reasoning effort. Key from a Worker secret `OPENROUTER_API_KEY` declared in `infra/alchemy.run.ts`; timeout; retries on 408/429/502/503 honouring `Retry-After`.
- Response and error bodies are never logged (moderation errors can echo comment text).
- Input is typed so only redacted comment text, Question text, Dimension scores and changes, and redacted Action titles can be passed; no Person, name, id, or time fits the type.

## Tests
- A unit test asserts the request body above byte for byte and that no fallback is possible.
- A privacy test that the input type rejects a Person id or name.
- A fake `AiClient` layer for later slices.

## Follows
ADR 0015, ADR 0009

## Context

Planned on the [Wayfinder map](https://github.com/chrisdoc/surveybeat-next/issues/85). Use `GLOSSARY.md` terms throughout. ADRs are in `docs/adr/`; research in `docs/research/`.
import { Context, Data, type Effect } from "effect";
import type { OutgoingEmail } from "./Email.ts";

/**
 * The provider clearly refused the message, so it was not sent. `permanent` rejections
 * (a suppressed recipient, an invalid header) fail at once; the others are retried.
 */
export class EmailRejected extends Data.TaggedError("EmailRejected")<{
  readonly code: string;
  readonly permanent: boolean;
}> {}

/** The provider gave no clear answer. The message may or may not have been sent, so it is never resent. */
export class EmailOutcomeUnknown extends Data.TaggedError("EmailOutcomeUnknown")<{
  readonly code: string;
}> {}

/** The provider accepted the message. Delivery is reported later, as a `DeliveryEvent`. */
export interface EmailAccepted {
  readonly messageId: string;
}

/**
 * Hands one message to an email provider. Cloudflare Email Sending in production; a recording
 * adapter everywhere else. Postmark is the documented fallback behind the same interface.
 */
export class EmailSender extends Context.Service<
  EmailSender,
  {
    readonly send: (
      message: OutgoingEmail,
    ) => Effect.Effect<EmailAccepted, EmailRejected | EmailOutcomeUnknown>;
  }
>()("@surveybeat/domain/EmailSender") {}
import { Schema } from "effect";
import { EmailAddress } from "../email/Email.ts";

/** A WorkOS user (`user_…`). One per human across every Organization. */
export const WorkosUserId = Schema.String.pipe(Schema.brand("WorkosUserId"));
export type WorkosUserId = typeof WorkosUserId.Type;

/** The WorkOS organization (`org_…`) an Organization maps to one to one (SPEC §4). */
export const WorkosOrganizationId = Schema.String.pipe(Schema.brand("WorkosOrganizationId"));
export type WorkosOrganizationId = typeof WorkosOrganizationId.Type;

/** A WorkOS session (`session_…`), the access token's `sid` claim. */
export const SessionId = Schema.String.pipe(Schema.brand("SessionId"));
export type SessionId = typeof SessionId.Type;

/** A Person within one Organization. */
export const PersonId = Schema.String.pipe(Schema.brand("PersonId"));
export type PersonId = typeof PersonId.Type;

/**
 * Emails are compared case-insensitively everywhere: in the index, the allowlist, and linking.
 * Lower-casing the whole address (local part included) is what every mainstream provider does.
 * NFKC first, so compatibility forms of a character compare as one.
 */
export const normaliseEmail = (email: string): string => email.normalize("NFKC").trim().toLowerCase();

const isPrintableAscii = (text: string): boolean => /^[\x20-\x7e]*$/.test(text);

/** Who signed in, as the identity provider vouches for them. `email` is normalised. */
export interface Identity {
  readonly userId: WorkosUserId;
  readonly email: EmailAddress;
  readonly emailVerified: boolean;
  /**
   * Only a verified, printable-ASCII email (as the provider sent it) may link to a Person or open the
   * "Create an Organization" path (ADR 0002). A non-ASCII address can sign in but never matches:
   * normalising it (U+212A KELVIN SIGN lower-cases to `k`) could make a different mailbox equal.
   */
  readonly emailMatchable: boolean;
}

/** The identity for the address the provider sent, normalised. */
export const identityOf = (userId: WorkosUserId, email: string, emailVerified: boolean): Identity => ({
  userId,
  email: EmailAddress.make(normaliseEmail(email)),
  emailVerified,
  emailMatchable: emailVerified && isPrintableAscii(email.trim()),
});

/**
 * The operator allowlist for creating an Organization (ADR 0002): comma-separated emails,
 * configured per stage in `infra/org-creation-allowlist.yaml` and bound as `ORG_CREATION_ALLOWLIST`.
 */
export class OrganizationCreationAllowlist {
  private readonly emails: ReadonlySet<string>;

  constructor(raw: string) {
    this.emails = new Set(
      raw
        .split(",")
        .map(normaliseEmail)
        .filter((email) => email.length > 0),
    );
  }

  /** An unverified or non-ASCII email is never allowlisted, whatever it says. */
  allows(identity: Identity): boolean {
    return identity.emailMatchable && this.emails.has(normaliseEmail(identity.email));
  }
}
